 {
 	struct net_device *dev = skb->dev;
 	struct netdev_queue *txq = NULL;
 	struct Qdisc *q;
 	int rc = -ENOMEM;
 	bool again = false;

 	skb_reset_mac_header(skb);
 	skb_assert_len(skb);

