 		     (SKBTX_SCHED_TSTAMP | SKBTX_BPF)))
 		__skb_tstamp_tx(skb, NULL, NULL, skb->sk, SCM_TSTAMP_SCHED);

 	/* Disable soft irqs for various locks below. Also
 	 * stops preemption for RCU.
